"use client"

/** Clean-room proposal editor. Sections reorder by pointer or keyboard. */

import * as React from "react"
import { GripVertical } from "lucide-react"

import { Badge } from "@/components/ui/badge"
import { Checkbox } from "@/components/ui/checkbox"
import { cn } from "@/lib/utils"
import { moveSection, preflightReady, type PreflightItem, type ProposalSection } from "@/lib/proposal"
import { Stepper, type StepperStep } from "@/components/ui/stepper"

export type ProposalContact = {
  name: string
  role: string
  email: string
}

export type ProposalDocumentProps = {
  sections: readonly ProposalSection[]
  onSectionsChange: (sections: ProposalSection[]) => void
  /** Sections stay put. Omitted, they still drag and move with the arrow keys. */
  readOnly?: boolean
  variables: Readonly<Record<string, string>>
  phases: readonly { id: string; label: string; hours: string }[]
  preflight: readonly PreflightItem[]
  onPreflight: (id: string, done: boolean) => void
  readyLabel?: string
  notReadyLabel?: string
  preflightTitle?: string
  contact: ProposalContact
  contactTitle?: string
  timeline: readonly StepperStep[]
  timelineIndex?: number
  timelineLabel?: string
  reorderLabel?: string
  className?: string
}

function paint(body: string, variables: Readonly<Record<string, string>>) {
  const parts = body.split(/(\{[a-z0-9]+\})/gi)
  return parts.map((part, index) => {
    const token = part.match(/^\{([a-z0-9]+)\}$/i)
    if (!token) return <React.Fragment key={index}>{part}</React.Fragment>
    const key = token[1]
    const value = variables[key] ?? part
    return (
      <span key={index} className="rounded bg-muted px-1 text-foreground">
        {value}
      </span>
    )
  })
}

export function ProposalDocument({
  sections,
  onSectionsChange,
  readOnly = false,
  variables,
  phases,
  preflight,
  onPreflight,
  readyLabel = "Ready to send",
  notReadyLabel = "Not ready",
  preflightTitle = "Pre-flight",
  contact,
  contactTitle = "Contact",
  timeline,
  timelineIndex = 0,
  timelineLabel = "Timeline",
  reorderLabel = "Reorder",
  className,
}: ProposalDocumentProps) {
  const ready = preflightReady(preflight)
  const dragId = React.useRef<string | null>(null)

  const move = (id: string, direction: -1 | 1) => {
    onSectionsChange(moveSection(sections, id, direction))
  }

  return (
    <div data-slot="proposal-document" className={cn("grid min-w-0 gap-4 lg:grid-cols-[minmax(12rem,16rem)_minmax(0,1fr)]", className)}>
      <div className="grid h-fit gap-4">
        <ol aria-label={reorderLabel} className="flex flex-col gap-1">
          {sections.map((section, index) => (
            <li
              key={section.id}
              draggable={!readOnly}
              onDragStart={() => {
                if (readOnly) return
                dragId.current = section.id
              }}
              onDragOver={(event) => event.preventDefault()}
              onDrop={() => {
                if (readOnly) return
                const from = dragId.current
                dragId.current = null
                if (!from || from === section.id) return
                const fromIndex = sections.findIndex((item) => item.id === from)
                const direction = fromIndex < index ? 1 : -1
                let next = [...sections]
                let cursor = fromIndex
                while (cursor !== index) {
                  next = moveSection(next, from, direction)
                  cursor += direction
                }
                onSectionsChange(next)
              }}
              className="flex min-w-0 items-center gap-1 rounded-lg border border-border bg-card px-1 py-1"
            >
              <button
                type="button"
                className="grid size-7 shrink-0 place-items-center rounded-md text-muted-foreground hover:bg-muted"
                aria-label={`${reorderLabel} ${section.title}`}
                disabled={readOnly}
                onKeyDown={(event) => {
                  if (readOnly) return
                  if (event.key === "ArrowUp") {
                    event.preventDefault()
                    move(section.id, -1)
                  }
                  if (event.key === "ArrowDown") {
                    event.preventDefault()
                    move(section.id, 1)
                  }
                }}
              >
                <GripVertical className="size-4" />
              </button>
              <span className="min-w-0 flex-1 truncate text-sm">
                {index + 1}. {section.title}
              </span>
            </li>
          ))}
        </ol>
        <section aria-label={preflightTitle} className="rounded-xl border border-border p-3">
          <div className="flex items-center justify-between gap-2">
            <h2 className="text-sm font-medium">{preflightTitle}</h2>
            <Badge variant={ready ? "default" : "outline"}>{ready ? readyLabel : notReadyLabel}</Badge>
          </div>
          <ul className="mt-2 flex flex-col gap-2">
            {preflight.map((item) => (
              <li key={item.id} className="flex items-start gap-2 text-sm">
                <Checkbox
                  checked={item.done}
                  onCheckedChange={(checked) => onPreflight(item.id, checked === true)}
                  aria-label={item.label}
                  className="mt-0.5"
                />
                <span className="wrap-break-word">{item.label}</span>
              </li>
            ))}
          </ul>
        </section>
      </div>
      <div className="grid min-w-0 gap-4">
        <article className="min-w-0 rounded-xl border border-border bg-card px-4 py-6 shadow-sm sm:px-8">
          {sections.map((section) => (
            <section key={section.id} className="mb-6 last:mb-0">
              <h2 className="text-base font-medium">{section.title}</h2>
              <p className="mt-2 text-sm leading-6 wrap-break-word text-muted-foreground">{paint(section.body, variables)}</p>
            </section>
          ))}
          <div className="min-w-0 max-w-full overflow-x-auto">
            <table className="w-full text-sm">
              <tbody>
                {phases.map((phase) => (
                  <tr key={phase.id} className="border-t border-border">
                    <td className="py-2 pe-3">{phase.label}</td>
                    <td className="py-2 text-end tabular-nums text-muted-foreground">{phase.hours}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </article>
        <div className="grid gap-3 sm:grid-cols-2">
          <section className="rounded-xl border border-border p-3" aria-label={contactTitle}>
            <h2 className="text-sm font-medium">{contactTitle}</h2>
            <p className="mt-2 text-sm">{contact.name}</p>
            <p className="text-xs text-muted-foreground">{contact.role}</p>
            <p className="text-xs text-muted-foreground wrap-break-word">{contact.email}</p>
          </section>
          <section aria-label={timelineLabel}>
            <h2 className="mb-2 text-sm font-medium">{timelineLabel}</h2>
            <Stepper steps={[...timeline]} current={timelineIndex} label={timelineLabel} compact />
          </section>
        </div>
      </div>
    </div>
  )
}

/**
 * Proposal workflow helpers. Data in, numbers out. No fetching and no theme.
 * Clean-room behavior: no product names, sample copy, or assets from any demo.
 */

import { moveItem } from "@/lib/reorder"

export const PROPOSAL_TABS = [
  "summary",
  "discovery",
  "scope",
  "similar",
  "estimate",
  "price",
  "risks",
  "proposal",
  "sow",
  "activity",
] as const

export type ProposalTabId = (typeof PROPOSAL_TABS)[number]

export type ProposalActionTone = "risk" | "price" | "low-confidence" | "follow-up"

export type ScopeOrigin = "adapted" | "edited" | "added"

export type ScopeTask = {
  id: string
  title: string
  hours: number
  origin?: ScopeOrigin
  included: boolean
}

export type ScopePhase = {
  id: string
  title: string
  tasks: readonly ScopeTask[]
}

export type ClarifyEffect = {
  id: string
  label: string
  hours: number
}

export type ClarifyOption = {
  value: string
  label: string
  effects: readonly ClarifyEffect[]
}

export type ClarifyQuestion = {
  id: string
  prompt: string
  detail?: string
  options: readonly ClarifyOption[]
}

export type ClarificationImpact = {
  previous: number
  next: number
  delta: number
  reasons: ClarifyEffect[]
  priceLow: number
  priceHigh: number
  weeksLow: number
  weeksHigh: number
}

export type EstimateLine = {
  id: string
  phase: string
  hours: number
  rate: number
  historicalHours: number
}

export type EstimateTotals = {
  hours: number
  amount: number
  historicalHours: number
}

export type PriceLineKind = "base" | "upsell" | "downsell"

export type PriceLine = {
  id: string
  label: string
  amount: number
  kind: PriceLineKind
}

export type ProposalSection = {
  id: string
  title: string
  body: string
}

export type PreflightItem = {
  id: string
  label: string
  done: boolean
}

export function scopeHours(phases: readonly ScopePhase[]): number {
  return phases.reduce(
    (sum, phase) =>
      sum + phase.tasks.reduce((inner, task) => inner + (task.included ? task.hours : 0), 0),
    0,
  )
}

export function phaseShares(phases: readonly ScopePhase[]) {
  return phases.map((phase) => ({
    key: phase.id,
    label: phase.title,
    value: phase.tasks.reduce((sum, task) => sum + (task.included ? task.hours : 0), 0),
  }))
}

export function toggleScopeTask(phases: readonly ScopePhase[], taskId: string): ScopePhase[] {
  return phases.map((phase) => ({
    ...phase,
    tasks: phase.tasks.map((task) =>
      task.id === taskId ? { ...task, included: !task.included } : task,
    ),
  }))
}

export function clarificationImpact({
  baseHours,
  questions,
  answers,
  rate,
  hoursPerWeek,
}: {
  baseHours: number
  questions: readonly ClarifyQuestion[]
  answers: Readonly<Record<string, string>>
  rate: number
  hoursPerWeek: number
}): ClarificationImpact {
  const reasons: ClarifyEffect[] = []
  for (const question of questions) {
    const chosen = answers[question.id]
    const option = question.options.find((item) => item.value === chosen)
    if (option) reasons.push(...option.effects)
  }
  const delta = reasons.reduce((sum, effect) => sum + effect.hours, 0)
  const next = Math.max(0, baseHours + delta)
  const weekly = hoursPerWeek > 0 ? hoursPerWeek : 1
  const safeRate = Number.isFinite(rate) ? rate : 0
  return {
    previous: baseHours,
    next,
    delta,
    reasons,
    priceLow: Math.round(next * safeRate * 0.92),
    priceHigh: Math.round(next * safeRate * 1.12),
    weeksLow: Math.round((next / weekly) * 10) / 10,
    weeksHigh: Math.round(((next / weekly) * 1.3) * 10) / 10,
  }
}

export function estimateAmount(line: EstimateLine): number {
  return line.hours * line.rate
}

export function estimateTotals(lines: readonly EstimateLine[]): EstimateTotals {
  return lines.reduce<EstimateTotals>(
    (totals, line) => ({
      hours: totals.hours + line.hours,
      amount: totals.amount + estimateAmount(line),
      historicalHours: totals.historicalHours + line.historicalHours,
    }),
    { hours: 0, amount: 0, historicalHours: 0 },
  )
}

export function priceTotal(lines: readonly PriceLine[]): number {
  return lines.reduce((sum, line) => sum + line.amount, 0)
}

export function clampPrice(value: number, min: number, max: number): number {
  const low = Math.min(min, max)
  const high = Math.max(min, max)
  if (!Number.isFinite(value)) return low
  return Math.min(high, Math.max(low, value))
}

export function moveSection(sections: readonly ProposalSection[], id: string, direction: -1 | 1): ProposalSection[] {
  const from = sections.findIndex((section) => section.id === id)
  if (from < 0) return [...sections]
  return moveItem(sections, from, from + direction)
}

export function preflightReady(items: readonly PreflightItem[]): boolean {
  return items.length > 0 && items.every((item) => item.done)
}

export function shareRatio(value: number, max: number): number {
  if (!Number.isFinite(value) || !Number.isFinite(max) || max <= 0) return 0
  return Math.max(0, Math.min(1, value / max))
}

export function formatHours(value: number, locale = "en-US"): string {
  return new Intl.NumberFormat(locale, { maximumFractionDigits: 1 }).format(value)
}

export function formatMoney(value: number, locale = "en-US", currency = "USD"): string {
  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    maximumFractionDigits: 0,
  }).format(value)
}

